            { segments: cycle.segments, punches: cycle.punches, flipArc: false }
        ];

        // Horizontal Mirror (Flip Y): Left turns become Right turns. Arc Convexity flips.
        if (cycle.symmetry === 'horizontal' || cycle.symmetry === 'full') {
            variants.push({
                segments: cycle.segments.map(s => ({ ...s, angleChange: -s.angleChange })),
                punches: cycle.punches.map(p => ({ ...p, relY: -p.relY, relRotation: -p.relRotation })),
                flipArc: true
            });
        }
        // Vertical Mirror (Flip X): Left turns become Right turns. Arc Convexity flips.
        if (cycle.symmetry === 'vertical' || cycle.symmetry === 'full') {
