                        // Ignore angleChange for arcs!
                        if (firstPat.arcCenterLeft !== undefined && startSeg.center) {
                            const isActualLeft = isCenterLeft(startP1, startP2, startSeg.center);
                            let expectedLeft = variant.flipArc ? !firstPat.arcCenterLeft : firstPat.arcCenterLeft;

                            // FIX: If traversing backwards, handedness relative to vector flips.
                            if (expectReverse) expectedLeft = !expectedLeft;

                            if (isActualLeft !== expectedLeft) continue;
