                            const wx = origin.x + rx;
                            const wy = origin.y + ry;

                            // Absolute Rotation
                            const wr = p.relRotation + (baseAngle * 180 / Math.PI);

                            resultPunches.push({
                                toolId: p.toolId,
                                x: wx,
                                y: wy,
                                rotation: wr,
                                lineId: `teach_${cycle.name}_${generateId()}`
                            });
                        });

                        // Mark all segments involved
                        matchedIndices.forEach(idx => markCoveredIncludingDuplicates(idx));

                        break; // Move to next Start Segment
                    }
                }
            }
        }
    });

    return { matches: resultPunches, coveredSegmentIndices: coveredIndices };
};

