 * Robust matching:
 * - Lines: Length + Vector Direction (angleChange)
 * - Arcs: Chord Length + Radius + Curvature Side (arcCenterLeft) [Ignoring angleChange]
 */
export const findTeachCycleMatches = (
    partGeometry: ProcessedGeometry,
    teachCycles: TeachCycle[],
    originalGeometry: PartGeometry // Needed for Probe Check
): { matches: Omit<PlacedTool, 'id'>[], coveredSegmentIndices: Set<number> } => {

    const resultPunches: Omit<PlacedTool, 'id'>[] = [];
    const coveredIndices = new Set<number>();

    const TOL_LEN = 1.0; // mm length/radius tolerance
    const TOL_ANG = 10.0; // degrees direction tolerance for lines
    const TOL_CONN_SQ = 1.0; // squared distance for connectivity

    const targetSegments = partGeometry.segments;

    // Helper: Compare two values with tolerance
    const matchesVal = (v1: number, v2: number, tol: number) => Math.abs(v1 - v2) < tol;

    // Helper: Denormalize point for Inside Check
    const toWorld = (p: Point) => ({ x: p.x + originalGeometry.bbox.minX, y: p.y + originalGeometry.bbox.minY });

    // Pre-calculate Pattern Probe Status (Is first punch inside?)
    // This resolves ambiguity between Horizontal and Vertical mirrors for L-shapes.
    const patternProbeStatus = new Map<string, boolean>();
    teachCycles.forEach(cycle => {
        if(cycle.punches.length > 0) {
            // Reconstruct probe in original context is hard here without the original geometry.
            // We assume the user taught a valid cycle.
            // We will just compare Variants against each other on the Target.
            // Strategy: We don't know if Pattern punch was Inside or Outside (usually Inside).
            // But usually, Horizontal and Vertical mirrors of an L-shape produce opposite Inside/Outside states.
            // We assume the correct match preserves the "Inside-ness" relative to the corner.
            // Ideally, we'd store `isInside` in PatternPunch. 
            // For now, let's assume matches must be INSIDE the part if the tool is not a specialized edge tool?
            // Better: Check validity of punch on target. If tool center is inside/outside.
        }
    });

    // Helper: Recursively mark segment and its spatial duplicates as covered
    const markCoveredIncludingDuplicates = (idx: number) => {
        if (coveredIndices.has(idx)) return;
        coveredIndices.add(idx);

        const source = targetSegments[idx];
        const TOL_DUP_SQ = 0.05; 

        for(let j=0; j<targetSegments.length; j++) {
            if(j === idx || coveredIndices.has(j)) continue;
            const candidate = targetSegments[j];
            if(candidate.type !== source.type) continue;

            // Check coincidence (fuzzy matching endpoints)
            const d11 = distSq(source.p1, candidate.p1);
            const d22 = distSq(source.p2, candidate.p2);
            const d12 = distSq(source.p1, candidate.p2);
            const d21 = distSq(source.p2, candidate.p1);

            const isSame = (d11 < TOL_DUP_SQ && d22 < TOL_DUP_SQ) || (d12 < TOL_DUP_SQ && d21 < TOL_DUP_SQ);

            if(isSame) {
                if(source.type === 'arc') {
                    if(Math.abs((source.radius||0) - (candidate.radius||0)) < 0.5) {
                        markCoveredIncludingDuplicates(j); 
                    }
                } else {
                    markCoveredIncludingDuplicates(j); 
                }
            }
        }
    };

    teachCycles.forEach(cycle => {
        if (cycle.segments.length === 0) return;

        // Generate Symmetry Variants
        // Horizontal Mirror (Flip Y): Angle -> -Angle. Y -> -Y. Rot -> -Rot.
        // Vertical Mirror (Flip X): Angle -> -Angle. X -> -X. Rot -> 180 - Rot.

        const variants = [
            { id: 'orig', segments: cycle.segments, punches: cycle.punches, flipArc: false }
        ];

        if (cycle.symmetry === 'horizontal' || cycle.symmetry === 'full') {
            variants.push({
                id: 'horz',
                segments: cycle.segments.map(s => ({ ...s, angleChange: -s.angleChange })),
                punches: cycle.punches.map(p => ({ ...p, relY: -p.relY, relRotation: -p.relRotation })),
                flipArc: true
            });
        }

        if (cycle.symmetry === 'vertical' || cycle.symmetry === 'full') {
             variants.push({
                id: 'vert',
                segments: cycle.segments.map(s => ({ ...s, angleChange: -s.angleChange })),
                punches: cycle.punches.map(p => ({ ...p, relX: -p.relX, relRotation: 180 - p.relRotation })), 
                flipArc: true
             });
        }

        if (cycle.symmetry === 'full') {
             variants.push({
                id: 'full',
                segments: cycle.segments, 
                punches: cycle.punches.map(p => ({ ...p, relX: -p.relX, relY: -p.relY })), // Rot 180
                flipArc: false 
             });
        }

        // Search in target geometry
        for (let i = 0; i < targetSegments.length; i++) {
            if (coveredIndices.has(i)) continue;

            const startSeg = targetSegments[i];

            // Try both Start Directions (Normal vs Reverse)
            // Reverse direction is crucial for finding rotated/mirrored corners 
            // where the winding order relative to the start point is flipped.
            const startDirections = [false, true];

            for (const startReverse of startDirections) {
                if (coveredIndices.has(i)) break; 

                // Define geometric properties of the start segment in this direction
                const startP1 = startReverse ? startSeg.p2 : startSeg.p1;
                const startP2 = startReverse ? startSeg.p1 : startSeg.p2;

                // Base Angle for this potential match's coordinate system
                const baseAngle = Math.atan2(startP2.y - startP1.y, startP2.x - startP1.x);
                const origin = startP1;

                // Try to match against all symmetry variants
                for (const variant of variants) {
                    if (coveredIndices.has(i)) break;

                    const patSegs = variant.segments;
                    const firstPat = patSegs[0];

                    // --- 1. Check FIRST Segment Match ---
                    if (startSeg.type !== firstPat.type) continue;
                    if (!matchesVal(dist(startP1, startP2), firstPat.length, TOL_LEN)) continue;

                    // Arc Check (First Segment)
                    if (firstPat.type === 'arc') {
                        if (!startSeg.radius || !firstPat.radius || !matchesVal(startSeg.radius, firstPat.radius, TOL_LEN)) continue;

                        // Arc Direction Check
                        if (firstPat.arcCenterLeft !== undefined && startSeg.center) {
                            const isActualLeft = isCenterLeft(startP1, startP2, startSeg.center);
                            const expectedLeft = variant.flipArc ? !firstPat.arcCenterLeft : firstPat.arcCenterLeft;
                            // Note: We do NOT flip expectation based on startReverse. 
                            // We treat the candidate chain as a self-consistent geometry.
                            if (isActualLeft !== expectedLeft) continue;
                        }
                    }

                    // --- 2. Check Chain Continuity ---
                    const matchedIndices = [i];
                    let currentEndpoint = startP2;
                    let matchFound = true;

                    for (let k = 1; k < patSegs.length; k++) {
                        const patSeg = patSegs[k];
                        let foundNextIndex = -1;
                        let nextReverse = false;

                        // Search for next segment
                        for(let t=0; t<targetSegments.length; t++) {
                            if (matchedIndices.includes(t) || coveredIndices.has(t)) continue;

                            const candidate = targetSegments[t];

                            if (candidate.type !== patSeg.type) continue;
                            if (!matchesVal(dist(candidate.p1, candidate.p2), patSeg.length, TOL_LEN)) continue;

                            // Connectivity
                            let isReverseCand = false;
                            if (distSq(currentEndpoint, candidate.p1) < TOL_CONN_SQ) {
                                isReverseCand = false;
                            } else if (distSq(currentEndpoint, candidate.p2) < TOL_CONN_SQ) {
                                isReverseCand = true;
                            } else {
                                continue;
                            }

                            // Define Candidate Vectors
                            const candP1 = isReverseCand ? candidate.p2 : candidate.p1;
                            const candP2 = isReverseCand ? candidate.p1 : candidate.p2;

                            // --- GEOMETRIC MATCHING LOGIC ---
                            let isGeoMatch = false;

                            if (patSeg.type === 'line') {
                                // For Lines: Check Relative Angle (Direction)
                                const candAngle = Math.atan2(candP2.y - candP1.y, candP2.x - candP1.x);
                                const diff = normalizeAngle((candAngle - baseAngle) * 180 / Math.PI);

                                if (matchesVal(diff, patSeg.angleChange, TOL_ANG)) {
                                    isGeoMatch = true;
                                }
                            } else if (patSeg.type === 'arc') {
                                // For Arcs: Check Radius & Bend Side (Ignore AngleChange)
                                if (candidate.radius && patSeg.radius && matchesVal(candidate.radius, patSeg.radius, TOL_LEN)) {
                                    if (patSeg.arcCenterLeft !== undefined && candidate.center) {
                                        const isActualLeft = isCenterLeft(candP1, candP2, candidate.center);
                                        const expectedLeft = variant.flipArc ? !patSeg.arcCenterLeft : patSeg.arcCenterLeft;
                                        if (isActualLeft === expectedLeft) {
                                            isGeoMatch = true;
                                        }
                                    }
                                }
                            }

                            if (isGeoMatch) {
                                foundNextIndex = t;
                                nextReverse = isReverseCand;
                                break;
                            }
                        }

                        if (foundNextIndex !== -1) {
                            matchedIndices.push(foundNextIndex);
                            const chosen = targetSegments[foundNextIndex];
                            currentEndpoint = nextReverse ? chosen.p1 : chosen.p2;
                        } else {
                            matchFound = false;
                            break;
                        }
                    }

                    if (matchFound) {
                        // --- PROBE CHECK ---
                        // Resolve ambiguity (L-shape Horz vs Vert Mirror) by checking if punches land Inside.
                        // We assume valid punches should be INSIDE the part (unless tool is specialized edge tool, but typically holes are inside).
                        // If we have punches, test the first one.
                        let isValidVariant = true;

                        if (cycle.punches.length > 0) {
                            const p = variant.punches[0];
                            const rx = p.relX * Math.cos(baseAngle) - p.relY * Math.sin(baseAngle);
                            const ry = p.relX * Math.sin(baseAngle) + p.relY * Math.cos(baseAngle);
                            const wx = origin.x + rx;
                            const wy = origin.y + ry;

                            const worldPoint = toWorld({x: wx, y: wy});
                            const isInside = isPointInsideContour(worldPoint, originalGeometry);

                            // Heuristic: If we are not sure what the original pattern was (Inside/Outside),
                            // we rely on the fact that usually punches are INSIDE.
                            // If we hit Outside, it's likely the wrong symmetry variant (e.g. Mirror Y instead of Mirror X for L-shape).
                            if (!isInside) {
                                isValidVariant = false;
                            }
                        }

                        if (isValidVariant) {
                            // Match Confirmed! Apply Punches
                            variant.punches.forEach(p => {
                                const rx = p.relX * Math.cos(baseAngle) - p.relY * Math.sin(baseAngle);
                                const ry = p.relX * Math.sin(baseAngle) + p.relY * Math.cos(baseAngle);

                                const wx = origin.x + rx;
                                const wy = origin.y + ry;

                                const wr = p.relRotation + (baseAngle * 180 / Math.PI);

                                resultPunches.push({
                                    toolId: p.toolId,
                                    x: wx,
                                    y: wy,
                                    rotation: wr,
                                    lineId: `teach_${cycle.name}_${generateId()}`
                                });
                            });

                            // Mark all segments involved
                            matchedIndices.forEach(idx => markCoveredIncludingDuplicates(idx));
                            break; // Move to next Start Segment
                        }
                    }
                }
            }
        }
    });

    return { matches: resultPunches, coveredSegmentIndices: coveredIndices };
};
